// 🔍 Image Analysis & Preparation from Google Drive
const inputData = $input.all();

if (!inputData || inputData.length === 0) {
  throw new Error('No image downloaded from Google Drive!');
}

const firstItem = inputData[0];
let imageData;
let fileName = 'enhanced_image';
let fileSize = 0;
let driveFileInfo = {};

// Get file info from Google Drive
if (firstItem.json) {
  driveFileInfo = {
    drive_file_id: firstItem.json.id,
    drive_file_name: firstItem.json.name,
    drive_modified_time: firstItem.json.modifiedTime,
    drive_size: firstItem.json.size,
    drive_mime_type: firstItem.json.mimeType
  };
  fileName = firstItem.json.name || fileName;
}

// Check for binary data
if (firstItem.binary && Object.keys(firstItem.binary).length > 0) {
  const binaryKey = Object.keys(firstItem.binary)[0];
  imageData = firstItem.binary[binaryKey].data;
  fileSize = imageData.length;

  console.log(`📸 Processing Google Drive image: ${fileName}`);
  console.log(`📏 Original size: ${Math.round(fileSize / 1024)} KB`);
  console.log(`🆔 Drive File ID: ${driveFileInfo.drive_file_id}`);

  return [{
    json: {
      success: true,
      source: 'Google Drive',
      original_filename: fileName,
      original_size_kb: Math.round(fileSize / 1024),
      processing_method: 'Free AI Upscaling',
      timestamp: new Date().toISOString(),
      ready_for_enhancement: true,
      drive_info: driveFileInfo
    },
    binary: {
      image: {
        data: imageData,
        mimeType: driveFileInfo.drive_mime_type || 'image/jpeg',
        fileName: fileName
      }
    }
  }];
} else {
  throw new Error('No image data found in downloaded file. Please ensure the file is a valid image (JPG, PNG, etc.)');
}

// 🎯 Smart Result Processor & Quality Enhancer (Google Drive Version)
const huggingfaceResult = $('🚀 HuggingFace Upscaler (Method 1)').all();
const deepaiResult = $('⚡ DeepAI Upscaler (Method 2)').all();
const cloudinaryResult = $('☁️ Cloudinary Enhancer (Method 3)').all();
const originalInfo = $('🔍 Analyze Drive Image').first().json;

let bestResult = null;
let method = '';
let enhancedData = null;
let downloadUrl = '';

console.log('🔍 Checking results from all methods for Drive image...');
console.log(`📁 Processing: ${originalInfo.original_filename} from Google Drive`);

// Try Hugging Face first (usually best quality)
if (huggingfaceResult && huggingfaceResult.length > 0 && huggingfaceResult[0].binary?.data) {
  console.log('✅ Hugging Face method succeeded');
  bestResult = huggingfaceResult[0];
  method = 'Hugging Face Swin2SR';
  enhancedData = bestResult.binary.data.data;
} 
// Try DeepAI as backup
else if (deepaiResult && deepaiResult.length > 0 && deepaiResult[0].json?.output_url) {
  console.log('✅ DeepAI method succeeded');
  method = 'DeepAI Super Resolution';
  downloadUrl = deepaiResult[0].json.output_url;

  // Download the enhanced image
  const downloadResponse = await $http.request({
    method: 'GET',
    url: downloadUrl,
    responseType: 'arraybuffer'
  });

  enhancedData = Buffer.from(downloadResponse.data);
}
// Try Cloudinary as final backup
else if (cloudinaryResult && cloudinaryResult.length > 0 && cloudinaryResult[0].json?.secure_url) {
  console.log('✅ Cloudinary method succeeded');
  method = 'Cloudinary AI Enhancement';
  downloadUrl = cloudinaryResult[0].json.secure_url;

  // Download the enhanced image
  const downloadResponse = await $http.request({
    method: 'GET',
    url: downloadUrl,
    responseType: 'arraybuffer'
  });

  enhancedData = Buffer.from(downloadResponse.data);
}
else {
  throw new Error('❌ All enhancement methods failed. Please try again with a different image.');
}

// Generate enhanced filename with Drive prefix
const timestamp = new Date().toISOString().split('T')[0];
const enhancedFileName = originalInfo.original_filename.replace(
  /\.(jpg|jpeg|png|webp)$/i,
  `_enhanced_${method.toLowerCase().replace(/\s+/g, '_')}_${timestamp}.png`
);

// Calculate enhancement stats
const enhancedSizeKB = Math.round(enhancedData.length / 1024);
const sizeIncrease = Math.round(((enhancedSizeKB - originalInfo.original_size_kb) / originalInfo.original_size_kb) * 100);

console.log(`🎉 Enhancement complete! Size: ${enhancedSizeKB}KB (${sizeIncrease > 0 ? '+' : ''}${sizeIncrease}% change)`);

return [{
  json: {
    success: true,
    source: 'Google Drive Auto-Processing',
    enhancement_method: method,
    original_filename: originalInfo.original_filename,
    enhanced_filename: enhancedFileName,
    original_size_kb: originalInfo.original_size_kb,
    enhanced_size_kb: enhancedSizeKB,
    size_change_percent: sizeIncrease,
    quality_improvement: 'Upscaled and Enhanced',
    processing_time: new Date().toISOString(),
    download_ready: true,
    drive_info: originalInfo.drive_info,
    enhancement_stats: {
      method_used: method,
      resolution_improved: true,
      quality_enhanced: true,
      ai_processed: true,
      automated_from_drive: true
    }
  },
  binary: {
    enhanced_image: {
      data: enhancedData,
      mimeType: 'image/png',
      fileName: enhancedFileName
    }
  }
}];
